#include "ksGlobalUpdateService.h"
#include <algorithm>
#include <cstdlib>
#include <iostream>
#include <memory>
#include <new>
#include <vector>
namespace{bool tracking=false;uint64_t allocations=0;void check(bool v,const char*m){if(!v)throw std::logic_error(m);}}
void*operator new(std::size_t n){if(tracking)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](std::size_t n){return::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
int main(){try{using T=ks::GlobalUpdateService;static_assert(sizeof(T)<32768,"Global fixed storage grew unexpectedly");std::vector<uint8_t>m(1<<24);uint64_t graphs=0,phases=0,rejects=0,reads=0,writes=0;uint32_t components=0;unsigned maxDepth=0;
for(unsigned seed=0;seed<1024;++seed){std::fill(m.begin(),m.end(),0);auto put=[&](uint32_t a,uint32_t v,unsigned n){for(unsigned j=0;j<n;++j)m[a+j]=uint8_t(v>>(8*(n-1-j)));};const auto part=uint8_t(seed);put(0x174ae + 20*part,0x30000,4);m[0x17526]=part;m[0x167ba]=uint8_t(seed>>2);for(unsigned n=0;n<256;++n){m[0x30000 + n]=uint8_t(seed*17+n*13);m[0x168fc + n]=uint8_t(seed+n*7);}for(unsigned n:{95u,113u,119u,103u})m[0x30000 + n]=uint8_t(seed&3);put(0x1512e,uint16_t(seed+1),2);put(0x15132,uint16_t(seed*71),2);for(unsigned n=0;n<120;++n)m[0x15282 + n]=uint8_t(seed*31+n*3);for(unsigned n=0;n<256;++n){m[0x159f4 + n]=uint8_t(seed*17+n*13);m[0x15a7c + n]=uint8_t(seed+n*7);m[0x152fa + n]=uint8_t(seed*7+n*31);}auto s=std::make_unique<T>();int lastwrite=-1;unsigned count=0;
while(!s->complete()){const auto cost=s->nextClocks(lastwrite);check(cost,"Missing global phase");const auto component=s->component();const auto mask=s->components();unsigned callbacks=0;tracking=true;check(!s->advanceBefore(cost-1,[&](uint32_t,unsigned){++callbacks;return uint8_t(0);},[&](uint32_t,uint8_t,unsigned){++callbacks;},lastwrite),"Accepted insufficient global budget");check(!callbacks&&s->component()==component&&s->components()==mask&&s->nextClocks(lastwrite)==cost,"Rejected global budget changed state");++rejects;check(s->advanceBefore(cost,[&](uint32_t raw,unsigned){++reads;const auto a=raw&0xffffff;return a==0x400004||a==0x600004?uint8_t(255):m[a];},[&](uint32_t raw,uint8_t v,unsigned){++writes;const auto a=raw&0xffffff;m[a]=v;lastwrite=a<0x400000||(a>=0xfffd10&&a<0xffffa0)?int(a):-1;},lastwrite)==cost,"Global budget differs");tracking=false;if(s->effect().write)lastwrite=-1;maxDepth=std::max(maxDepth,s->coordinator().depth());check(++count<100000,"Global graph stalled");++phases;}
components|=s->components();++graphs;}
check(!allocations,"Global pure allocated");check(maxDepth==3,"Nested lookup fixture missed");std::cout<<"PASS Global pure graphs="<<graphs<<" phases="<<phases<<" budget_rejects="<<rejects<<" reads="<<reads<<" writes="<<writes<<" components="<<components<<" depth="<<maxDepth<<" bytes="<<sizeof(T)<<" allocations="<<allocations<<'\n';return 0;}catch(const std::exception&e){tracking=false;std::cerr<<e.what()<<'\n';return 1;}}
